adjust: 100%;\n}\n\n#app { display: flex; flex-direction: column; height: 100%; }\n\n/* ===== Update banner & status bar ===== */\n.update-banner {\n  display: flex; align-items: center; justify-content: space-between; gap: 12px;\n  background: #0078d4; color: #fff; padding: 10px 14px; font-size: 13px; flex-shrink: 0;\n}\n/* display:flex would otherwise beat the UA [hidden] rule */\n.update-banner[hidden] { display: none !important; }\n.update-banner-btn {\n  background: transparent; color: #fff; border: 1px solid #fff; border-radius: 4px;\n  padding: 5px 14px; font-family: inherit; font-size: 13px; cursor: pointer; flex-shrink: 0;\n}\n.update-banner-btn:hover { background: rgba(255,255,255,.15); }\n\n.status-bar {\n  display: flex; justify-content: space-between; align-items: center;\n  padding: 3px 10px; background: #f3f2f1; border-bottom: 1px solid #edebe9;\n  font-size: 10px; color: #a19f9d; flex-shrink: 0;\n}\n.build-id { font-family: Consolas, monospace; letter-spacing: .3px; }\n.autosave-indicator.ok { color: #0b6a0b; }\n.autosave-indicator.pending { color: #605e5c; }\n.autosave-indicator.error { color: #a4262c; font-weight: 700; }\n\n/* ===== Tabs ===== */\n.tab-bar {\n  display: flex; flex-shrink: 0; overflow-x: auto; overflow-y: hidden;\n  background: #fff; border-bottom: 1px solid #edebe9;\n  -webkit-overflow-scrolling: touch; scrollbar-width: none;\n}\n.tab-bar::-webkit-scrollbar { display: none; }\n\n.tab-btn {\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 2px; min-width: 58px; min-height: 46px; padding: 6px 10px;\n  border: none; background: transparent; color: #605e5c;\n  font-family: inherit; font-size: 10px; cursor: pointer; flex-shrink: 0;\n  border-bottom: 2px solid transparent; transition: color .15s, border-color .15s;\n  -webkit-tap-highlight-color: transparent;\n}\n.tab-btn:hover { color: #323130; background: #faf9f8; }\n.tab-btn.active { color: #0078d4; border-bottom-color: #0078d4; }\n.tab-ic